import {SHOPS,DISTRICTS,COLORS,COMPLETE,INCOMPLETE,KEEP,newGame,groups,groupIncome,income,holdings,claimPlots,beginBuild,canPlace,placeShop,finishYear,nextYear,emptyOffer,evaluateOffer,trade,rankings,validSave} from './engine.mjs';
const $=s=>document.querySelector(s),KEY='vietnamtown-save-v1';
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=validSave(saved)?saved:newGame();}catch{state=newGame();}
let view='play',selectedShop=null,selectedLot=null,chosen=[],partner=1,lastFocus=null,toastTimer=null;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${n.toLocaleString('en-US')} <span class="money-symbol">M₫</span>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('This browser cannot save progress. Keep this tab open to finish your game.');}}
function changed(){save();render();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function modal(title,content,eyebrow='VIETNAM TOWN'){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div><button class="close" aria-label="Close dialog" data-action="close">×</button></div><div class="modal-body">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){$('#modal').close();lastFocus?.focus?.();}
function lotLabel(l){const owner=l.owner===null?'Unclaimed':state.players[l.owner].name;return `Plot ${l.id+1}, ${DISTRICTS[Math.floor(l.id/12)]}, ${owner}${l.shop===null?', empty':', '+SHOPS[l.shop].name}${state.pending.includes(l.id)?', offered to you':''}`;}
function board(){return DISTRICTS.map((name,b)=>`<section class="district" aria-label="${name}"><div class="district-head"><strong>${name}</strong><span>Block ${String(b+1).padStart(2,'0')}</span></div><div class="district-grid">${state.lots.slice(b*12,b*12+12).map(l=>{const shop=l.shop===null?null:SHOPS[l.shop],offered=state.pending.includes(l.id);return `<button data-lot="${l.id}" class="lot ${l.owner!==null?'owned':''} ${l.owner===0?'mine':''} ${offered?'offered':''} ${chosen.includes(l.id)||selectedLot===l.id?'selected':''} ${state.phase==='build'&&selectedShop!==null&&canPlace(state,0,l.id,selectedShop)?'buildable':''}" style="--owner:${l.owner===null?'#8f9c7e':COLORS[l.owner]};--shop:${shop?.color??'#52694a'}" aria-label="${lotLabel(l)}" aria-pressed="${chosen.includes(l.id)||selectedLot===l.id}"><span class="lot-num">${l.id+1}</span>${l.owner!==null?`<span class="owner-initial">${l.owner===0?'Y':state.players[l.owner].name[0]}</span>`:''}${shop?`<span class="tile-code">${shop.code}</span><span class="tile-name">${shop.name}</span>`:`<span class="empty-lot">${chosen.includes(l.id)?'✓':offered?'◇':l.owner===0?'+':'·'}</span>`}</button>`;}).join('')}</div></section>`).join('');}
function phaseCard(){const y=state.year;let title,body,action;switch(state.phase){case'receive':title='Your next address.';body=`Choose ${state.draftCount} of the ${state.pending.length} outlined plots. Neighbors are valuable: keep addresses close together.`;action=`<div class="draft-picks">${state.pending.map(id=>`<button data-lot="${id}" class="draft-pick ${chosen.includes(id)?'picked':''}" aria-pressed="${chosen.includes(id)}">${id+1}</button>`).join('')}</div><button class="primary wide" data-action="claim" ${chosen.length!==state.draftCount?'disabled':''}>Claim ${chosen.length} / ${state.draftCount} plots →</button>`;break;case'trade':title="Let's talk business.";body='Trade plots, shop tiles, and cash. The right neighbor can change everything.';action='<button class="primary wide" data-action="trade">Make a deal ↗</button><button class="text-button" data-action="build">Ready to build →</button>';break;case'build':title='Open for business.';body='Select a shop tile below the board, then one of your empty plots. Match neighboring shops to earn more.';action=`<button class="primary wide" data-action="collect">Collect ${money(income(state,0))} income →</button><div class="phase-caption">${holdings(state,0).filter(l=>l.shop===null).length} empty plots · ${state.players[0].tiles.reduce((a,b)=>a+b,0)} tiles in hand</div>`;break;case'income':title='A good year on your street.';body=`Your shops earned ${state.lastIncome[0]} million ₫. New plots and tiles are waiting for next year.`;action=`<button class="primary wide" data-action="next">Begin year ${y+1} →</button><button class="text-button" data-action="income">See everyone's income</button>`;break;default:title='The neighborhood is complete.';body='Six years, countless possibilities. See whose deals built the most successful businesses.';action='<button class="primary wide" data-action="results">See final standings →</button><button class="text-button" data-action="new">Play another game</button>';}
return `<div class="turn-card"><div class="phase-steps"><span class="${state.phase==='receive'?'on':''}">01 Receive</span><span class="${state.phase==='trade'?'on':''}">02 Trade</span><span class="${state.phase==='build'?'on':''}">03 Build</span></div><p class="eyebrow">YEAR ${y} OF 6</p><h2>${title}</h2><p>${body}</p>${action}</div>`;}
function playerCard(){return `<div class="player-card"><div class="card-heading"><h3>Around the table</h3><span class="mini-label">YOU + 3 BOTS</span></div>${state.players.map((p,i)=>`<div class="player-row"><span class="avatar" style="--owner:${COLORS[i]}">${i===0?'Y':p.name[0]}</span><div><div class="player-name">${escape(p.name)}${i===0?' <span class="you-label">YOU</span>':''}</div><div class="player-sub">${holdings(state,i).length} plots · ${groups(state,i).length} businesses</div></div><div class="player-cash">${money(p.cash)}<small>+${income(state,i)} M₫ / year</small></div></div>`).join('')}</div>`;}
function hand(){return `<div class="hand"><div class="hand-heading"><h3>Your shop tiles <span class="count-badge">${state.players[0].tiles.reduce((a,b)=>a+b,0)}</span></h3><span>${state.phase==='build'?'Select a tile, then an empty plot':'A business grows one tile at a time'}</span></div><div class="tiles">${SHOPS.map((s,i)=>`<button class="shop-card ${selectedShop===i?'active':''}" style="--shop:${s.color}" data-shop="${i}" aria-pressed="${selectedShop===i}" aria-label="${s.name}, ${state.players[0].tiles[i]} tiles, ${s.size} connected tiles to complete"><span class="shop-abbr">${s.code}</span><span class="quantity">×${state.players[0].tiles[i]}</span><strong>${s.name}</strong><small>${s.size} to complete · ${COMPLETE[s.size]} M₫</small></button>`).join('')}</div><p class="inventory-help">${selectedShop!==null?`${SHOPS[selectedShop].english}: connect ${SHOPS[selectedShop].size} tiles to earn ${COMPLETE[SHOPS[selectedShop].size]} M₫ each year.`:'Same shop. Same owner. Shared edge. That’s how a business grows.'}</p></div>`;}
function selection(){if(selectedLot===null)return '';const l=state.lots[selectedLot];return `<div class="selected-panel"><div><strong>Plot ${l.id+1} · ${DISTRICTS[Math.floor(l.id/12)]}</strong><p>${l.owner===null?'Unclaimed address':`${l.owner===0?'Your address':escape(state.players[l.owner].name)+'’s address'} · ${l.shop===null?'Ready for a shop':SHOPS[l.shop].name}`}</p></div>${state.phase==='trade'&&l.owner!==null&&l.owner!==0?`<button class="primary" data-action="trade-lot" data-id="${l.id}">Make an offer</button>`:state.phase==='build'&&selectedShop!==null&&canPlace(state,0,l.id,selectedShop)?`<button class="primary" data-action="place">Open ${SHOPS[selectedShop].name}</button>`:'<button class="text-button" data-action="deselect">Close</button>'}</div>`;}
function render(){document.querySelectorAll('.nav-button').forEach(x=>x.classList.toggle('active',x.dataset.action===view));if(view==='research'){renderResearch();return;}$('#app').innerHTML=`<div class="game-heading"><div><p class="eyebrow">SÀI GÒN · A NEW CHAPTER</p><h1>A little street. A big possibility.</h1></div><div class="year-strip" aria-label="Year ${state.year} of 6"><span class="year-label">YEAR</span>${[1,2,3,4,5,6].map(y=>`<span class="year ${y===state.year?'current':y<state.year?'done':''}">${y}</span>`).join('')}</div></div><div class="layout"><section><div class="board-shell"><div class="panorama"><img src="/assets/saigon-street.png" alt="Pixel-art Vietnamese shophouses, street cafés, scooters, and greenery" width="2172" height="724"><div class="scene-label">SÀI GÒN, VIỆT NAM</div></div><div class="board-toolbar"><strong>${state.phase==='receive'?'Choose your addresses':'Your neighborhood'}</strong><div class="legend">${state.players.map((p,i)=>`<span><i class="dot" style="--owner:${COLORS[i]}"></i>${escape(p.name)}</span>`).join('')}<span><i class="dot" style="--owner:#bdc4af"></i>Unclaimed</span></div></div><div class="neighborhoods">${board()}</div><div class="board-foot"><span>72 plots · 6 neighborhoods</span><span>${state.phase==='receive'?'◇ Outlined plots are yours to choose from.':'Streets separate businesses. Diagonals don’t connect.'}</span></div></div>${selection()}${hand()}</section><aside class="sidebar">${phaseCard()}${playerCard()}<div class="tip"><strong>A little local wisdom</strong><br>${state.year<=2?'A good deal helps both sides. A plot beside your shop may be worth more than two plots across town.':state.year<=4?'A complete business earns a bonus every year. Count how many paydays remain before making a deal.':'The last payday is getting close. Unused tiles and empty plots have no value at the end.'}<button class="tip-link" data-action="businesses">View your businesses ↗</button></div></aside></div><div class="game-bottom"><span>LOCAL GAME · Saved on this browser · All amounts are fictional million ₫</span><div><button data-action="history">Game journal</button> · <button data-action="new">New game</button></div></div>`;}
function clickLot(id){if(state.phase==='receive'){if(!state.pending.includes(id)){selectedLot=id;render();return;}selectedLot=null;if(chosen.includes(id))chosen=chosen.filter(x=>x!==id);else if(chosen.length<state.draftCount)chosen.push(id);else toast(`You can keep ${state.draftCount} plots. Deselect one first.`);render();return;}selectedLot=id;render();}
function openTrade(prefillLot=null){if(state.phase!=='trade')return toast('Deals open after you claim your plots, and close when you start building.');if(prefillLot!==null)partner=state.lots[prefillLot].owner;const buildSide=(player,key,label)=>`<section class="trade-side"><h3>${label}</h3><label class="trade-item">Cash (million ₫)<input name="${key}-cash" type="number" min="0" max="${state.players[player].cash}" step="1" value="0" aria-label="${label}: cash"></label><p class="mini-label">SHOP TILES</p>${SHOPS.map((s,i)=>`<label class="trade-item">${s.name} <span class="muted">(${state.players[player].tiles[i]})</span><input type="number" name="${key}-tile-${i}" min="0" max="${state.players[player].tiles[i]}" step="1" value="0" aria-label="${label}: ${s.name} tiles"></label>`).join('')}<p class="mini-label">PLOTS · SHOPS STAY ON THE PLOT</p><div class="trade-lots">${holdings(state,player).map(l=>`<label class="trade-lot" title="${lotLabel(l)}"><input type="checkbox" name="${key}-lot" value="${l.id}" ${key==='take'&&prefillLot===l.id?'checked':''}>${l.id+1}${l.shop!==null?' '+SHOPS[l.shop].code:''}</label>`).join('')||'<span class="muted">No plots yet</span>'}</div></section>`;modal('A good deal starts here.',`<form id="trade-form"><div class="trade-select"><label for="partner">Trade with</label><select id="partner" name="partner">${state.players.slice(1).map(p=>`<option value="${p.id}" ${p.id===partner?'selected':''}>${p.name} · ${p.cash} M₫</option>`).join('')}</select><span class="muted small">Computer neighbor</span></div><div class="trade-columns">${buildSide(0,'give','You give')}${buildSide(partner,'take','You receive')}</div><div id="trade-feedback" class="trade-feedback" role="status">Add any combination of cash, tiles, and plots. ${state.players[partner].name} values plots beside their own businesses.</div><div class="modal-actions"><button type="button" class="secondary" data-action="close">Back to the street</button><button type="submit" class="primary">Propose deal ↗</button></div></form>`,'TRADE · YEAR '+state.year);}
function readOffer(){const data=new FormData($('#trade-form'));const side=key=>({cash:Number(data.get(key+'-cash')),tiles:SHOPS.map((_,i)=>Number(data.get(key+'-tile-'+i))),lots:data.getAll(key+'-lot').map(Number)});return {partner:Number(data.get('partner')),give:side('give'),take:side('take')};}
function rules(){modal('Build a street worth coming back to.',`<p>You and three computer neighbors have six years to grow a business community. The most cash after the sixth payday wins.</p><ol><li><strong>Receive.</strong> Choose from your offered addresses, then receive shop tiles. You keep ${KEEP.join(', ')} plots in years 1–6. Tiles: 5 in year one, then 4 each year.</li><li><strong>Trade.</strong> Make as many deals as you like. Exchange cash, empty plots, built plots, and unused shop tiles. Both sides must accept; our computer neighbors assess each proposal.</li><li><strong>Build.</strong> Place any number of tiles on your own empty plots for free. Select a tile, select an address, then confirm. Placement is permanent. Unused tiles carry over.</li><li><strong>Collect.</strong> Every business pays every year, even one just opened. The game ends after year six’s income.</li></ol><h3>What counts as one business?</h3><p>Tiles of the same shop type and owner connect along shared edges inside one block. Diagonals and streets don’t connect. Match the shop’s target size to complete it.</p><table><thead><tr><th>Tiles</th><th>Incomplete income</th><th>Complete income</th></tr></thead><tbody>${[1,2,3,4,5,6].map(n=>`<tr><td>${n}</td><td>${n===6?'—':INCOMPLETE[n]+' M₫'}</td><td>${n>=3?COMPLETE[n]+' M₫':'—'}</td></tr>`).join('')}</tbody></table><p class="rules-note">Example: three connected Cà phê tiles earn 50 M₫ every year. Three connected Phở tiles earn 40 M₫; add a fourth to earn 80 M₫. Separate businesses are paid separately.</p><h3>Small but useful details</h3><ul><li>You start with 50 M₫. All amounts are fictional million đồng; these are game values.</li><li>No building costs, rent, interest, or end-game resale value. Tied cash is broken by most shop tiles on the board; an exact tie is shared.</li><li>A group larger than its target pays as complete target-sized sets plus an incomplete remainder. You can keep growing along the block.</li><li>Switching to Build closes trading for that year. Check your deals first.</li><li>Progress saves only in this browser. These are local computer opponents, not online players. Cash is visible in this adaptation.</li></ul><button class="primary wide" data-action="close">Back to the neighborhood</button>`,'HOW TO PLAY');}
function incomeModal(){modal(state.phase==='ended'?'The last payday.':'Another year in the books.',`<p>Every completed and incomplete business has paid its owner.</p>${state.players.map((p,i)=>`<div class="score-row"><span class="avatar" style="--owner:${COLORS[i]}">${i===0?'Y':p.name[0]}</span><span>${escape(p.name)}</span><strong>+${money(state.lastIncome[i]??0)}</strong><span class="muted">Total ${p.cash} M₫</span></div>`).join('')}<div class="modal-actions"><button class="primary" data-action="${state.phase==='ended'?'results':'next'}">${state.phase==='ended'?'Final standings':'Begin year '+(state.year+1)} →</button></div>`,'INCOME · YEAR '+state.year);}
function results(){const ranked=rankings(state),top=ranked[0].cash,topTiles=state.lots.filter(l=>l.owner===ranked[0].id&&l.shop!==null).length,winners=ranked.filter(p=>p.cash===top&&state.lots.filter(l=>l.owner===p.id&&l.shop!==null).length===topTiles);modal(winners.length>1?'A shared place at the top.':ranked[0].id===0?'This neighborhood is yours.':`${escape(ranked[0].name)} built a thriving neighborhood.`,`<p>${winners.length>1?winners.map(p=>escape(p.name)).join(' and ')+' tied':ranked[0].id===0?'You finished first':escape(ranked[0].name)+' finished first'} with ${top} million ₫ after six years.</p>${ranked.map((p,i)=>`<div class="score-row ${winners.some(w=>w.id===p.id)?'winner':''}"><span>${i+1}</span><span class="avatar" style="--owner:${COLORS[p.id]}">${p.id===0?'Y':p.name[0]}</span><span>${escape(p.name)}</span><strong>${money(p.cash)}</strong></div>`).join('')}<p class="muted">You made ${state.trades} accepted deals. Your businesses earned ${income(state,0)} M₫ in their final year. Unused tiles and empty plots have no final value. Cash ties are broken by the number of placed shop tiles.</p><div class="modal-actions"><button class="secondary" data-action="close">Explore the finished town</button><button class="primary" data-action="new">Start a new neighborhood</button></div>`,'SIX YEARS · FINAL STANDINGS');}
function businesses(){const g=groups(state,0);modal('Your businesses.',g.length?`<table><thead><tr><th>Business</th><th>Plots</th><th>Size / target</th><th>Yearly income</th></tr></thead><tbody>${g.map(b=>`<tr><td>${SHOPS[b.shop].name}</td><td>${b.lots.map(x=>x+1).join(', ')}</td><td>${b.size} / ${SHOPS[b.shop].size}${b.size>=SHOPS[b.shop].size?' ✓':''}</td><td>${groupIncome(b.shop,b.size)} M₫</td></tr>`).join('')}</tbody></table><strong>Total: ${income(state,0)} M₫ per year</strong>`:'<p>No shops open yet. During Build, choose a shop tile and place it on one of your empty plots.</p>','YOUR LITTLE EMPIRE');}
function renderResearch(){$('#app').innerHTML=`<article class="research"><p class="eyebrow">THE DESIGN NOTEBOOK</p><h1>From Chinatown to Vietnam Town.</h1><p class="research-intro">Keep the negotiation. Give it a neighborhood that feels like home. This prototype translates Chinatown’s business-building puzzle into an original, fictional map of Sài Gòn.</p><div class="info-chips"><span>6 years</span><span>72 addresses</span><span>6 Vietnamese businesses</span><span>You + 3 computer neighbors</span></div><div class="research-grid"><section class="research-card"><p class="eyebrow">01 · THE ORIGINAL</p><h2>The deal is the game.</h2><p>Karsten Hartwig’s <em>Chinatown</em> is a negotiation game for 3–5 players. Over six rounds, players receive building cards and business tiles, trade freely, place shops, and collect income. Cash at the end decides the winner; placed shop tiles break a tie. <a href="https://cdn.1j1ju.com/medias/46/fa/78-chinatown-rulebook.pdf" target="_blank" rel="noopener noreferrer">2014 rulebook ↗</a></p><p>The clever part is uneven value. An address that is forgettable to you might finish somebody else’s business. Random allocations create reasons to negotiate; the neighborhood grid makes those reasons visible.</p><p>Connected, same-owner shops form businesses. A business of its target size earns more, and earlier completion pays off repeatedly.</p></section><section class="research-card"><p class="eyebrow">02 · THE ADAPTATION</p><h2>A familiar kind of commerce.</h2><p>Vietnam Town is about neighborhood livelihoods: coffee houses, food shops, florists, tailors, and corner grocers. The vocabulary, storefront art, and place names carry the setting.</p><p>The six block names draw from places in Hồ Chí Minh City. Their placement is fictional, not a street map. Keeping Chợ Lớn in the town acknowledges the city’s Chinese-Vietnamese commercial heritage.</p><p>Use the same strategic question throughout: <em>“What can we trade so both of our streets work better?”</em></p></section></div><h2>Translate the mechanics, not just the labels.</h2><table><thead><tr><th>Chinatown mechanic</th><th>Vietnam Town interpretation</th><th>What it gives the player</th></tr></thead><tbody><tr><td>Building ownership cards</td><td>Numbered shop addresses in six neighborhood blocks</td><td>A visible reason to negotiate for adjacent space</td></tr><tr><td>Business tiles</td><td>Cà phê, Bánh mì, Phở, Tiệm hoa, Tiệm may, Tạp hóa</td><td>Distinct trades with target sizes from 3 to 6</td></tr><tr><td>Open negotiation</td><td>A two-sided offer of cash, addresses, and shop tiles</td><td>Package deals, counteroffers, and mutual benefit</td></tr><tr><td>Connected shops</td><td>Rows of matching businesses along the same block</td><td>Planning that depends on where other players own space</td></tr><tr><td>Annual income</td><td>Year-end shop earnings in fictional million đồng</td><td>A reason to build early and value remaining paydays</td></tr><tr><td>Richest player wins</td><td>Most cash after the sixth year</td><td>A clear ending without extra scoring systems</td></tr></tbody></table><div class="research-grid"><section class="research-card"><p class="eyebrow">03 · PLAYABLE NOW</p><h2>A complete local game.</h2><ul><li>One player and three computer opponents.</li><li>Six full years of address drafting, negotiation, building, and income.</li><li>Arbitrary packages of plots, tiles, and cash, with bot acceptance and cash counteroffers.</li><li>Permanent placement, edge adjacency, ownership changes, income calculation, and final standings.</li><li>Automatic progress saving in this browser, plus a game journal.</li></ul><p><strong>Deliberate changes:</strong> 72 plots instead of the original 85, six shop types instead of twelve, a larger tile supply, adjusted draws, sequential address choices, visible money, and scripted opponents. The original income curve and overflow scoring are retained in game-sized đồng units. Bot negotiation is a first way to test the economy; it cannot reproduce human bargaining.</p></section><section class="research-card"><p class="eyebrow">04 · THE NEXT BUILD</p><h2>Bring friends to the table.</h2><ol><li><strong>Playtest the economy.</strong> Check completion rates, rejected deals, and whether all shop types remain useful.</li><li><strong>Add online rooms.</strong> Use authoritative shared game state, visible shop tiles and private cash, simultaneous offers, reconnects, and a ready check before building.</li><li><strong>Make the town come alive.</strong> Replace letter tiles with a consistent Aseprite sprite set; add ownership markers and opening animations.</li><li><strong>Refine the local voice.</strong> Add Vietnamese/English language choice and review details with Vietnamese players.</li></ol><p>Keep the visual identity, wording, and map original. A close commercial adaptation would need a separate rights review.</p></section></div><section class="research-card"><p class="eyebrow">ART DIRECTION</p><h2>Warm streets. Crisp pixels.</h2><p>An original pixel-art street panorama sets the scene. The downloadable Aseprite document contains the artwork on a single editable layer. The first playable tiles use clear two-letter markers so ownership and adjacency stay readable. For a production pass, create six shop sprites at a shared pixel scale, separate owner outlines from the art, and export PNG atlases from Aseprite.</p><p><a href="/assets/saigon-street.png" download>Download the street artwork</a> · <a href="/assets/saigon-street.aseprite" download>Download the editable Aseprite document</a></p></section><div class="source-links"><a href="https://boardgamegeek.com/boardgame/47/chinatown" target="_blank" rel="noopener noreferrer">Chinatown on BoardGameGeek ↗</a><a href="https://cdn.1j1ju.com/medias/46/fa/78-chinatown-rulebook.pdf" target="_blank" rel="noopener noreferrer">Z-Man Games rulebook (2014, mirrored) ↗</a></div><p class="muted" style="font-size:12px;margin-top:16px">Independent research prototype inspired by Chinatown. No affiliation with its designer or publisher. Original artwork; fictional neighborhood layout. Research checked September 2026.</p><button class="primary" data-action="play">Back to your neighborhood →</button></article>`;}
function act(action,el){switch(action){case'close':closeModal();break;case'play':view='play';render();window.scrollTo({top:0});break;case'research':view='research';render();window.scrollTo({top:0});break;case'rules':rules();break;case'claim':claimPlots(state,chosen);chosen=[];selectedLot=null;changed();toast('Addresses claimed. Your neighbors are ready to trade.');break;case'trade':openTrade();break;case'trade-lot':openTrade(Number(el.dataset.id));break;case'build':modal('Ready to open your shops?','<p>Starting Build closes trading for this year. You can place any number of your tiles, then collect income.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep trading</button><button class="primary" data-action="confirm-build">Start building →</button></div>','CLOSE THE DEALS');break;case'confirm-build':beginBuild(state);selectedLot=null;closeModal();changed();break;case'place':placeShop(state,selectedLot,selectedShop);toast(`${SHOPS[selectedShop].name} is open on plot ${selectedLot+1}.`);selectedLot=null;if(!state.players[0].tiles[selectedShop])selectedShop=null;changed();break;case'deselect':selectedLot=null;render();break;case'collect':{const possible=holdings(state,0).some(l=>SHOPS.some((_,s)=>canPlace(state,0,l.id,s)));if(possible)modal('Finish building for this year?','<p>You still have tiles that could fit on your empty plots. You may keep them for a future year, or open more shops now.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep building</button><button class="primary" data-action="confirm-collect">Collect income →</button></div>','YEAR-END');else act('confirm-collect');break;}case'confirm-collect':finishYear(state);selectedLot=null;selectedShop=null;changed();incomeModal();break;case'income':incomeModal();break;case'next':nextYear(state);chosen=[];selectedLot=null;selectedShop=null;closeModal();changed();break;case'results':results();break;case'businesses':businesses();break;case'history':modal('From the neighborhood journal.',`<ul class="history">${state.logs.map(l=>`<li>${escape(l)}</li>`).join('')}</ul>`,'YOUR GAME');break;case'new':modal('A fresh start on a new street?','<p>This replaces the game saved in this browser. Your current neighborhood will not be recoverable.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep this game</button><button class="primary" data-action="confirm-new">Start a new game</button></div>','NEW GAME');break;case'confirm-new':state=newGame();selectedLot=null;selectedShop=null;chosen=[];view='play';closeModal();changed();toast('A new neighborhood, full of possibilities.');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-lot],[data-shop]');if(!el)return;try{if(el.dataset.lot!==undefined)clickLot(Number(el.dataset.lot));else if(el.dataset.shop!==undefined){selectedShop=selectedShop===Number(el.dataset.shop)?null:Number(el.dataset.shop);render();if(state.phase!=='build')toast('You can place these tiles during Build. Trade for the ones you need first.');}else act(el.dataset.action,el);}catch(error){toast(error.message);}});
document.addEventListener('change',e=>{if(e.target.id==='partner'){partner=Number(e.target.value);openTrade();}});
document.addEventListener('submit',e=>{if(e.target.id!=='trade-form')return;e.preventDefault();try{const offer=readOffer(),result=trade(state,offer);if(result.accepted){closeModal();changed();toast(`Deal accepted. ${state.players[offer.partner].name} says, “Good doing business with you!”`);}else{$('#trade-feedback').innerHTML=`${state.players[offer.partner].name}: “We’re not quite there. Add <strong>${result.shortfall} M₫</strong> to your offer, or change the package.”`;}}catch(error){$('#trade-feedback').textContent=error.message;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();save();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'get_neighborhood_state',description:'Read the local Vietnam Town game: phase, players, plots, shop tiles and offered addresses.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(state))});register({name:'claim_neighborhood_plots',description:'Complete the Receive phase by claiming the required number of offered plots. Plot IDs are zero-based.',inputSchema:{type:'object',properties:{plotIds:{type:'array',items:{type:'integer'},uniqueItems:true}},required:['plotIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{claimPlots(state,input.plotIds);chosen=[];changed();return {phase:state.phase,ownedPlots:holdings(state,0).map(l=>l.id)};}});register({name:'start_neighborhood_build',description:'Close trading for this year and start the Build phase.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{beginBuild(state);changed();return {phase:state.phase};}});register({name:'place_neighborhood_shop',description:'Permanently place one shop tile on your empty plot during Build. Plot IDs and shop indices are zero-based.',inputSchema:{type:'object',properties:{plotId:{type:'integer'},shopIndex:{type:'integer'}},required:['plotId','shopIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const result=placeShop(state,input.plotId,input.shopIndex);changed();return {...result,annualIncome:income(state,0)};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
